import { test, expect } from '@playwright/test';

test.describe('todos page', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/todos');
  });

  test('shows the seed todos', async ({ page }) => {
    await expect(page.getByRole('list', { name: 'Todo list' }).getByRole('listitem')).toHaveCount(3);
  });

  test('adds a todo', async ({ page }) => {
    await page.getByLabel('New todo').fill('Learn fixtures');
    await page.getByRole('button', { name: 'Add' }).click();
    await expect(page.getByText('Learn fixtures')).toBeVisible();
  });
});

test('uses the request fixture and baseURL', async ({ request, baseURL }) => {
  expect(baseURL).toBeTruthy();
  const res = await request.get('/api/health');
  await expect(res).toBeOK();
});
